const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs/promises");
const path = require("node:path");
let createUsbPrinterProvider, sameDevice, createPrintTransport, chunkBytes, TRANSPORT_ERRORS;
let ESCPOS_COMMANDS, concatBytes, getPaperProfile, PAPER_PROFILES, createEncoding, UTF8_ENCODING, createReceiptModel, EscPosFormatter, formatLayout, createLayout, buildCustomerReceiptLayout, buildKitchenReceiptLayout;
let createPrintRequest, createPrintResult, createPrintDecision, createDecisionLayer, createPrintPipeline;

test.before(async () => {
  const source = await fs.readFile(path.join(__dirname, "..", "public", "js", "usb-printer-provider.js"), "utf8");
  const loaded = await import("data:text/javascript;base64," + Buffer.from(source).toString("base64"));
  createUsbPrinterProvider = loaded.createUsbPrinterProvider; sameDevice = loaded.sameDevice;
  const transportSource = await fs.readFile(path.join(__dirname, "..", "public", "js", "print-transport.js"), "utf8");
  const transport = await import("data:text/javascript;base64," + Buffer.from(transportSource).toString("base64"));
  createPrintTransport = transport.createPrintTransport; chunkBytes = transport.chunkBytes; TRANSPORT_ERRORS = transport.TRANSPORT_ERRORS;
  const moduleSource = async name => fs.readFile(path.join(__dirname, "..", "public", "js", name), "utf8");
  const dataUrl = source => "data:text/javascript;base64," + Buffer.from(source).toString("base64");
  const commandSource = await moduleSource("escpos-commands.js"), paperSource = await moduleSource("paper-profile.js"), encodingSource = await moduleSource("printer-encoding.js"), receiptSource = await moduleSource("receipt-model.js");
  const commands = await import(dataUrl(commandSource)), paper = await import(dataUrl(paperSource)), encoding = await import(dataUrl(encodingSource)), receipt = await import(dataUrl(receiptSource));
  ESCPOS_COMMANDS = commands.ESCPOS_COMMANDS; concatBytes = commands.concatBytes; getPaperProfile = paper.getPaperProfile; PAPER_PROFILES = paper.PAPER_PROFILES; createEncoding = encoding.createEncoding; UTF8_ENCODING = encoding.UTF8_ENCODING; createReceiptModel = receipt.createReceiptModel;
  let layoutSource = await moduleSource("receipt-layout.js");
  layoutSource = layoutSource.replace("./receipt-model.js", dataUrl(receiptSource));
  const layout = await import(dataUrl(layoutSource)); createLayout = layout.createLayout; buildCustomerReceiptLayout = layout.buildCustomerReceiptLayout; buildKitchenReceiptLayout = layout.buildKitchenReceiptLayout;
  let formatterSource = await moduleSource("escpos-formatter.js");
  formatterSource = formatterSource.replace("./escpos-commands.js", dataUrl(commandSource)).replace("./paper-profile.js", dataUrl(paperSource)).replace("./printer-encoding.js", dataUrl(encodingSource));
  const formatter = await import(dataUrl(formatterSource)); EscPosFormatter = formatter.EscPosFormatter; formatLayout = formatter.formatLayout;
  const requestSource = await moduleSource("print-request.js"), decisionSource = await moduleSource("print-decision.js");
  let resultSource = await moduleSource("print-result.js"); resultSource = resultSource.replace("./print-request.js", dataUrl(requestSource));
  const requestModule = await import(dataUrl(requestSource)), resultModule = await import(dataUrl(resultSource)), decisionModule = await import(dataUrl(decisionSource));
  createPrintRequest = requestModule.createPrintRequest; createPrintResult = resultModule.createPrintResult; createPrintDecision = decisionModule.createPrintDecision; createDecisionLayer = decisionModule.createDecisionLayer;
  let pipelineSource = await moduleSource("print-pipeline.js"); pipelineSource = pipelineSource.replace("./print-request.js", dataUrl(requestSource)).replace("./print-result.js", dataUrl(resultSource));
  createPrintPipeline = (await import(dataUrl(pipelineSource))).createPrintPipeline;
});

function usb(overrides = {}) { const handlers = {}; return Object.assign({ handlers, getDevices: async()=>[], requestDevice: async()=>null, addEventListener(n,c){handlers[n]=c;}, removeEventListener(n,c){if(handlers[n]===c)delete handlers[n];} }, overrides); }
function device(overrides = {}) { return Object.assign({ productName:"Receipt", manufacturerName:"Maker", vendorId:1, productId:2, serialNumber:"S1", opened:false, configuration:null, configurations:[{configurationValue:1,interfaces:[{interfaceNumber:0,alternates:[{alternateSetting:0,endpoints:[{direction:"out",endpointNumber:1,packetSize:64}]}]}]}], async open(){this.opened=true;}, async selectConfiguration(v){this.configuration={configurationValue:v};}, async claimInterface(){}, async releaseInterface(){}, async selectAlternateInterface(){}, async close(){this.opened=false;} }, overrides); }
const tick = () => new Promise(resolve => setTimeout(resolve, 0));
function transportDriver(overrides={}) { const listeners=[];return Object.assign({chunks:[],getStatus:()=>({status:"connected",capability:{packetSize:4}}),async transferChunk(chunk){this.chunks.push(Array.from(chunk));return {ok:true,bytesTransferred:chunk.byteLength};},onStatusChanged(callback){listeners.push(callback);return()=>{const i=listeners.indexOf(callback);if(i>=0)listeners.splice(i,1);};},emit(status){listeners.slice().forEach(callback=>callback({status}));},listenerCount(){return listeners.length;}},overrides); }
function pipelineDependencies(overrides={}) { const calls=[];return Object.assign({calls,decision:createDecisionLayer(()=>({action:"print",tickets:[{type:"customer",layoutVariant:"customer",paper:"58",copies:1}]})),layoutBuilders:{customer:(order)=>{calls.push("layout");return createLayout("customer",[{type:"line",value:order.name||"Item"}]);}},formatter:(layout)=>{calls.push("format");return formatLayout(layout);},transport:{async send(bytes){calls.push("send");return{bytesTransferred:bytes.byteLength};}},provider:"usb",clock:()=>100},overrides); }

test("1 environment null", () => assert.equal(createUsbPrinterProvider({environment:null}).getStatus().status,"unsupported"));
test("2 environment without usb", () => assert.equal(createUsbPrinterProvider({environment:{}}).available,false));
test("3 getDevices empty", async()=>{const p=createUsbPrinterProvider({environment:{usb:usb()}});assert.deepEqual(await p.detect(),[]);assert.equal(p.getStatus().status,"no_device");});
test("4 getDevices one auto-selects", async()=>{const d=device(),p=createUsbPrinterProvider({environment:{usb:usb({getDevices:async()=>[d]})}});await p.detect();assert.equal(p.getStatus().status,"selected");assert.equal(d.opened,false);});
test("5 getDevices multiple stays available", async()=>{const p=createUsbPrinterProvider({environment:{usb:usb({getDevices:async()=>[device(),device({serialNumber:"S2"})]})}});await p.detect();assert.equal(p.getStatus().status,"device_available");assert.equal(p.getStatus().devices.length,2);});
test("6 select authorized device", async()=>{const p=createUsbPrinterProvider({environment:{usb:usb({getDevices:async()=>[device(),device({serialNumber:"S2"})]})}});const list=await p.detect();await p.selectAuthorizedDevice(list[1].key);assert.equal(p.getStatus().selectedDevice.serialNumber,"S2");});
test("7 selected device remains after refresh", async()=>{const d=device(),u=usb({getDevices:async()=>[d]}),p=createUsbPrinterProvider({environment:{usb:u}});await p.detect();await p.connect();await p.detect();assert.equal(p.getStatus().status,"connected");});
test("8 stale selected device is cleared", async()=>{const d=device();let list=[d];const p=createUsbPrinterProvider({environment:{usb:usb({getDevices:async()=>list})}});await p.detect();list=[];await p.detect();assert.equal(p.getStatus().status,"device_not_found");assert.equal(p.getStatus().selectedDevice,null);});
test("9 requestDevice success", async()=>{const p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>device()})}});assert.equal((await p.requestDevice([])).productName,"Receipt");});
test("10 requestDevice NotFoundError", async()=>{const e=Object.assign(new Error(),{name:"NotFoundError"});const p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>{throw e;}})}});await p.requestDevice();assert.equal(p.getStatus().status,"selection_cancelled");});
test("11 requestDevice permission errors", async()=>{for(const name of ["SecurityError","NotAllowedError"]){const e=Object.assign(new Error(),{name});const p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>{throw e;}})}});await p.requestDevice();assert.equal(p.getStatus().status,"permission_denied");}});
test("12 connect without selection", async()=>{const p=createUsbPrinterProvider({environment:{usb:usb()}});await p.connect();assert.equal(p.getStatus().status,"device_not_found");});
test("13 open success", async()=>{const d=device(),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().connected,true);});
test("14 open failure", async()=>{const d=device({open:async()=>{throw new Error("busy");}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().status,"connection_failed");});
test("15 existing configuration is preserved", async()=>{const config={configurationValue:2,interfaces:[{interfaceNumber:0,alternates:[{alternateSetting:0,endpoints:[{direction:"out",endpointNumber:1,packetSize:64}]}]}]};const d=device({configuration:config,configurations:[config],selectConfiguration:async()=>{throw new Error("called");}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().status,"connected");});
test("16 fallback configuration", async()=>{const d=device({configurations:[{configurationValue:7,interfaces:[{interfaceNumber:2,alternates:[{alternateSetting:0,endpoints:[{direction:"out",endpointNumber:3,packetSize:32}]}]}]}]}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(d.configuration.configurationValue,7);});
test("17 no configuration", async()=>{const d=device({configurations:[]}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().status,"connection_failed");});
test("18 selectConfiguration failure", async()=>{const d=device({selectConfiguration:async()=>{throw new Error("bad");}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().status,"connection_failed");});
test("19 repeated connect", async()=>{let n=0;const d=device({open:async function(){n++;this.opened=true;}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.connect();assert.equal(n,1);});
test("20 repeated disconnect", async()=>{let n=0;const d=device({close:async function(){n++;this.opened=false;}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.disconnect();await p.disconnect();assert.equal(n,1);});
test("21 close failure", async()=>{const d=device({close:async()=>{throw new Error("close");}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.disconnect();assert.equal(p.getStatus().status,"error");});
test("22 connect and disconnect serialize", async()=>{const d=device(),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await Promise.all([p.connect(),p.disconnect()]);assert.equal(p.getStatus().status,"disconnected");});
test("23 browser connect event queues behind connect", async()=>{const d=device();const u=usb({requestDevice:async()=>d,getDevices:async()=>[d]});const p=createUsbPrinterProvider({environment:{usb:u}});await p.requestDevice();const connecting=p.connect();u.handlers.connect({device:d});await connecting;await tick();assert.equal(p.getStatus().status,"connected");});
test("24 matching physical disconnect", async()=>{const d=device(),u=usb({requestDevice:async()=>d}),p=createUsbPrinterProvider({environment:{usb:u}});await p.requestDevice();await p.connect();u.handlers.disconnect({device:d});await tick();assert.equal(p.getStatus().status,"device_disconnected");});
test("25 unrelated physical disconnect", async()=>{const d=device(),u=usb({requestDevice:async()=>d}),p=createUsbPrinterProvider({environment:{usb:u}});await p.requestDevice();u.handlers.disconnect({device:device({serialNumber:"OTHER"})});await tick();assert.equal(p.getStatus().status,"selected");});
test("26 same VID PID without serial are distinct",()=>assert.equal(sameDevice(device({serialNumber:""}),device({serialNumber:""})),false));
test("27 listener unsubscribe", async()=>{let n=0;const p=createUsbPrinterProvider({environment:{usb:usb()}}),off=p.onStatusChanged(()=>n++);off();await p.detect();assert.equal(n,0);});
test("28 throwing listener is isolated", async()=>{const old=console.error;console.error=()=>{};const p=createUsbPrinterProvider({environment:{usb:usb()}});p.onStatusChanged(()=>{throw new Error();});await p.detect();console.error=old;assert.equal(p.getStatus().status,"no_device");});
test("29 destroy listener cleanup",()=>{const u=usb(),p=createUsbPrinterProvider({environment:{usb:u}});p.destroy();assert.equal(u.handlers.connect,undefined);assert.equal(u.handlers.disconnect,undefined);});
test("30 operations after destroy are controlled", async()=>{const p=createUsbPrinterProvider({environment:{usb:usb()}});p.destroy();const result=await p.connect();assert.equal(result.status,"error");});
test("31 metadata JSON excludes USBDevice", async()=>{const raw=device({secret:{native:true}}),p=createUsbPrinterProvider({environment:{usb:usb({getDevices:async()=>[raw]})}});await p.detect();const json=JSON.stringify(p.getStatus());assert.equal(json.includes("secret"),false);assert.equal(json.includes("opened"),false);});
test("32 USB module failure has Printer Center fallback", async()=>{let source=await fs.readFile(path.join(__dirname,"..","public","js","printer-center.js"),"utf8");source=source.replace(/^import .*printer-profile\.js";$/m,'const PrinterProfile={};').replace(/^import .*print-queue\.js";$/m,'const PrintQueue={};');global.window={};const loaded=await import("data:text/javascript;base64,"+Buffer.from(source).toString("base64"));const old=console.error;console.error=()=>{};const fallback=await loaded.initializeUsbProvider(()=>Promise.reject(new Error("404")));console.error=old;assert.equal(fallback.available,false);assert.equal(loaded.UsbProvider.getStatus().status,"unsupported");});
test("33 connected device cannot be switched before disconnect", async()=>{const a=device({serialNumber:"A"}),b=device({serialNumber:"B"});const p=createUsbPrinterProvider({environment:{usb:usb({getDevices:async()=>[a,b]})}});const list=await p.detect();await p.selectAuthorizedDevice(list[0].key);await p.connect();const blocked=await p.selectAuthorizedDevice(list[1].key);assert.equal(a.opened,true);assert.equal(blocked.connected,true);assert.equal(blocked.selectedDevice.serialNumber,"A");assert.equal(blocked.status,"connected");assert.match(blocked.message,/先中斷/);await p.disconnect();const selected=await p.selectAuthorizedDevice(list[1].key);assert.equal(selected.selectedDevice.serialNumber,"B");assert.equal(selected.status,"selected");});
test("34 requestDevice is not queued behind an active operation", async()=>{let finishDetect;const pending=new Promise(resolve=>{finishDetect=resolve;});let chooserCalls=0;const u=usb({getDevices:async()=>pending,requestDevice:async()=>{chooserCalls++;return device();}});const p=createUsbPrinterProvider({environment:{usb:u}});const detecting=p.detect();const busy=await p.requestDevice([]);assert.equal(chooserCalls,0);assert.equal(busy.status,"error");assert.match(busy.message,/正在處理其他操作/);finishDetect([]);await detecting;assert.equal(chooserCalls,0);});
test("35 idle requestDevice invokes chooser synchronously", async()=>{let chooserCalls=0,finishChooser;const chooser=new Promise(resolve=>{finishChooser=resolve;});const p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:()=>{chooserCalls++;return chooser;}})}});const requested=p.requestDevice([]);assert.equal(chooserCalls,1);finishChooser(device());const selected=await requested;assert.equal(selected.productName,"Receipt");assert.equal(p.getStatus().status,"selected");});
test("36 busy requestDevice never retries automatically", async()=>{let finishDetect;const pending=new Promise(resolve=>{finishDetect=resolve;});let chooserCalls=0;const p=createUsbPrinterProvider({environment:{usb:usb({getDevices:async()=>pending,requestDevice:async()=>{chooserCalls++;return device();}})}});const detecting=p.detect();await p.requestDevice([]);finishDetect([]);await detecting;await tick();assert.equal(chooserCalls,0);await p.requestDevice([]);assert.equal(chooserCalls,1);});
test("37 pending chooser success cannot restore state after destroy", async()=>{let resolveChooser;const chooser=new Promise(resolve=>{resolveChooser=resolve;});let openCalls=0,listenerCalls=0;const selectedDevice=device({open:async()=>{openCalls++;}});const p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:()=>chooser})}});p.onStatusChanged(()=>listenerCalls++);const requested=p.requestDevice([]);assert.equal(listenerCalls,1);const destroyed=p.destroy();resolveChooser(selectedDevice);const result=await requested;assert.equal(result,null);assert.equal(p.getStatus().status,destroyed.status);assert.equal(p.getStatus().selectedDevice,null);assert.deepEqual(p.getStatus().devices,[]);assert.equal(p.getStatus().connected,false);assert.equal(listenerCalls,1);await p.connect();assert.equal(openCalls,0);});
test("38 pending chooser rejection cannot alter destroyed state", async()=>{let rejectChooser;const chooser=new Promise((resolve,reject)=>{rejectChooser=reject;});let listenerCalls=0;const p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:()=>chooser})}});p.onStatusChanged(()=>listenerCalls++);const requested=p.requestDevice([]);assert.equal(listenerCalls,1);const destroyed=p.destroy();const cancellation=Object.assign(new Error("cancel"),{name:"NotFoundError"});rejectChooser(cancellation);const result=await requested;assert.equal(result,null);assert.equal(p.getStatus().status,destroyed.status);assert.notEqual(p.getStatus().status,"selection_cancelled");assert.notEqual(p.getStatus().status,"permission_denied");assert.equal(p.getStatus().selectedDevice,null);assert.deepEqual(p.getStatus().devices,[]);assert.equal(listenerCalls,1);});
test("39 configuration discovery does not assume configuration one", async()=>{const d=device({configurations:[{configurationValue:9,interfaces:[{interfaceNumber:4,alternates:[{alternateSetting:0,endpoints:[{direction:"out",endpointNumber:6,packetSize:128}]}]}]}]}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().capability.configuration,9);});
test("40 interface discovery does not assume interface zero", async()=>{let claimed;const d=device({configurations:[{configurationValue:1,interfaces:[{interfaceNumber:7,alternates:[{alternateSetting:0,endpoints:[{direction:"out",endpointNumber:2,packetSize:64}]}]}]}],claimInterface:async n=>{claimed=n;}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(claimed,7);assert.equal(p.getStatus().capability.interfaceNumber,7);});
test("41 OUT endpoint discovery captures endpoint and packet size", async()=>{const d=device({configurations:[{configurationValue:1,interfaces:[{interfaceNumber:0,alternates:[{alternateSetting:0,endpoints:[{direction:"in",endpointNumber:1,packetSize:8},{direction:"out",endpointNumber:5,packetSize:512}]}]}]}]}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().capability.endpointNumber,5);assert.equal(p.getStatus().capability.packetSize,512);});
test("42 alternate discovery selects non-default alternate", async()=>{let selected;const d=device({configurations:[{configurationValue:1,interfaces:[{interfaceNumber:3,alternates:[{alternateSetting:0,endpoints:[]},{alternateSetting:2,endpoints:[{direction:"out",endpointNumber:4,packetSize:32}]}]}]}],selectAlternateInterface:async(i,a)=>{selected=[i,a];}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.deepEqual(selected,[3,2]);});
test("43 claim succeeds once and driver becomes ready", async()=>{let claims=0;const d=device({claimInterface:async()=>{claims++;}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.connect();assert.equal(claims,1);assert.equal(p.getStatus().status,"connected");});
test("44 claim failure maps CLAIM_FAILED and closes device", async()=>{const d=device({claimInterface:async()=>{throw new Error("claim");}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().lastErrorCode,"CLAIM_FAILED");assert.equal(d.opened,false);});
test("45 disconnect releases interface before close", async()=>{const order=[];const d=device({releaseInterface:async n=>order.push("release:"+n),close:async function(){order.push("close");this.opened=false;}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.disconnect();assert.deepEqual(order,["release:0","close"]);});
test("46 release failure maps RELEASE_FAILED but still closes", async()=>{const d=device({releaseInterface:async()=>{throw new Error("release");}}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.disconnect();assert.equal(p.getStatus().lastErrorCode,"RELEASE_FAILED");assert.equal(d.opened,false);});
test("47 disconnect cleanup clears capability", async()=>{const d=device(),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.ok(p.getStatus().capability);await p.disconnect();assert.equal(p.getStatus().capability,null);});
test("48 capability cache is preferred on reconnect", async()=>{const ep=n=>({direction:"out",endpointNumber:n,packetSize:64});const config={configurationValue:1,interfaces:[{interfaceNumber:0,alternates:[{alternateSetting:0,endpoints:[ep(1),ep(2)]}]}]};const d=device({configurations:[config]}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.disconnect();config.interfaces[0].alternates[0].endpoints=[ep(2),ep(1)];await p.connect();assert.equal(p.getStatus().capability.endpointNumber,1);});
test("49 stale capability cache rebuilds", async()=>{const ep=n=>({direction:"out",endpointNumber:n,packetSize:64});const config={configurationValue:1,interfaces:[{interfaceNumber:0,alternates:[{alternateSetting:0,endpoints:[ep(1)]}]}]};const d=device({configurations:[config]}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();await p.disconnect();config.interfaces[0].alternates[0].endpoints=[ep(8)];await p.connect();assert.equal(p.getStatus().capability.endpointNumber,8);});
test("50 NO_CONFIGURATION mapping", async()=>{const d=device({configurations:[]}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();assert.equal(p.getStatus().lastErrorCode,"NO_CONFIGURATION");});
