test("148 decision failure is isolated",async()=>{const result=await createPrintPipeline(pipelineDependencies({decision:{decide:async()=>{throw Object.assign(new Error("decision"),{code:"DECISION_FAILED"});}}})).execute({});assert.equal(result.failed,true);assert.equal(result.errors[0].code,"DECISION_FAILED");});
test("149 layout failure is isolated",async()=>{const result=await createPrintPipeline(pipelineDependencies({layoutBuilders:{customer:()=>{throw new Error("layout");}}})).execute({});assert.equal(result.failed,true);assert.equal(result.success,false);});
test("150 transport failure is isolated",async()=>{const result=await createPrintPipeline(pipelineDependencies({transport:{send:async()=>{throw Object.assign(new Error("wire"),{code:"TRANSFER_TIMEOUT"});}}})).execute({});assert.equal(result.failed,true);assert.equal(result.errors[0].code,"TRANSFER_TIMEOUT");});
test("151 transfer cancellation produces cancelled result",async()=>{const result=await createPrintPipeline(pipelineDependencies({transport:{send:async()=>{throw Object.assign(new Error("cancel"),{code:"TRANSFER_CANCELLED"});}}})).execute({});assert.equal(result.cancelled,true);assert.equal(result.failed,false);});
test("152 concurrent pipeline call returns busy without unlocking active call",async()=>{let finish;const deps=pipelineDependencies({transport:{send:()=>new Promise(resolve=>{finish=()=>resolve({bytesTransferred:1});})}}),pipeline=createPrintPipeline(deps);const first=pipeline.execute({});await tick();const second=await pipeline.execute({});assert.equal(second.errors[0].code,"PIPELINE_BUSY");assert.equal(pipeline.isBusy(),true);finish();await first;assert.equal(pipeline.isBusy(),false);});
test("153 destroyed pipeline returns controlled closed result",async()=>{const pipeline=createPrintPipeline(pipelineDependencies());assert.equal(pipeline.destroy(),true);const result=await pipeline.execute({});assert.equal(result.failed,true);assert.equal(result.errors[0].code,"PIPELINE_CLOSED");});
test("154 pipeline destroy is idempotent",()=>{const pipeline=createPrintPipeline(pipelineDependencies());assert.equal(pipeline.destroy(),true);assert.equal(pipeline.destroy(),false);});
test("155 pipeline result remains immutable after execution",async()=>{const result=await createPrintPipeline(pipelineDependencies()).execute({order:{name:"A"}});assert.equal(Object.isFrozen(result),true);assert.equal(Object.isFrozen(result.errors),true);});
